fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    for i in (0..n).rev() {
        result.push(a[i]);
    }
    result
}

fn main() {
    let v = vec!['h', 'e', 'l', 'l', 'o'];
    let rev_v = reverse(&v);
    assert_eq!(rev_v, vec!['o', 'l', 'l', 'e', 'h']);
    println!("{:?} reversed is {:?}", v, rev_v);
}